import sys

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.tree = [(0, 0)] * (2 * self.size)
        # Fill leaves
        for i in range(self.n):
            self.tree[self.size + i] = (data[i], i + 1)  # data is 0-based, station indices are 1-based
        # Fill the rest
        for i in range(self.size - 1, 0, -1):
            left_val, left_idx = self.tree[2 * i]
            right_val, right_idx = self.tree[2 * i + 1]
            if left_val > right_val:
                self.tree[i] = (left_val, left_idx)
            elif right_val > left_val:
                self.tree[i] = (right_val, right_idx)
            else:
                self.tree[i] = (left_val, max(left_idx, right_idx))

    def query(self, l, r):
        # l and r are 1-based indices, inclusive
        res_val = -1
        res_idx = 0
        l += self.size - 1
        r += self.size - 1
        while l <= r:
            if l % 2 == 1:
                current_val, current_idx = self.tree[l]
                if current_val > res_val or (current_val == res_val and current_idx > res_idx):
                    res_val = current_val
                    res_idx = current_idx
                l += 1
            if r % 2 == 0:
                current_val, current_idx = self.tree[r]
                if current_val > res_val or (current_val == res_val and current_idx > res_idx):
                    res_val = current_val
                    res_idx = current_idx
                r -= 1
            l >>= 1
            r >>= 1
        return res_idx

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    if n == 1:
        print(0)
        return
    a = list(map(int, input[1:n]))
    st = SegmentTree(a)
    dp = [0] * (n + 1)  # dp[1..n-1]
    for i in range(n-1, 0, -1):
        ai = a[i-1]
        if ai == n:
            dp[i] = n - i
        else:
            L = i + 1
            R = ai
            R = min(R, n-1)
            if L > R:
                dp[i] = n - i
            else:
                max_idx = st.query(L, R)
                dp[i] = (n - i) + dp[max_idx] - (ai - max_idx)
    total = sum(dp[1:n])
    print(total)

if __name__ == "__main__":
    main()

