class SparseTable:
    def __init__(self, data):
        self.n = len(data)
        self.log_table = [0] * (self.n + 1)
        for i in range(2, self.n + 1):
            self.log_table[i] = self.log_table[i // 2] + 1
        self.k_max = self.log_table[self.n] + 1
        self.st = [[0] * self.n for _ in range(self.k_max)]
        self.st[0] = data[:]
        for j in range(1, self.k_max):
            for i in range(self.n - (1 << j) + 1):
                self.st[j][i] = max(self.st[j-1][i], self.st[j-1][i + (1 << (j-1))])

    def query(self, l, r):
        length = r - l + 1
        k = self.log_table[length]
        return max(self.st[k][l], self.st[k][r - (1 << k) + 1])

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n]))

