import sys
from functools import lru_cache

def main():
    m = int(sys.stdin.readline())

    def get_a(n):
        low = 1
        high = 10**6  # Sufficient for n up to 1e15
        while low <= high:
            mid = (low + high) // 2
            cube = mid * mid * mid
            if cube == n:
                return mid
            elif cube < n:
                low = mid + 1
            else:
                high = mid - 1
        return high

    @lru_cache(maxsize=None)
    def dfs(n):
        if n == 0:
            return (0, 0)
        a = get_a(n)
        # Option 1: take a^3
        blocks1, x1 = dfs(n - a**3)
        blocks1 += 1
        x1 += a**3
        # Option 2: take (a-1)^3 if a > 1
        if a > 1:
            remaining = (a**3 - 1) - (a-1)**3
            blocks2, x2 = dfs(remaining)
            blocks2 += 1
            x2 += (a-1)**3
            if blocks1 > blocks2:
                return (blocks1, x1)
            elif blocks1 < blocks2:
                return (blocks2, x2)
            else:
                return (blocks1, max(x1, x2))
        else:
            return (blocks1, x1)

    result_blocks, result_x = dfs(m)
    print(result_blocks, result_x)

if __name__ == "__main__":
