import sys
from collections import defaultdict

def generate_pattern(num_str):
    pattern = []
    for i in range(1, 19):
        if i <= len(num_str):
            digit = num_str[-i]
        else:
            digit = '0'
        parity = '0' if (int(digit) % 2 == 0) else '1'
        pattern.append(parity)
    return ''.join(pattern)

def generate_query_pattern(s):
    needed = 18 - len(s)
    return '0' * needed + s

def main():
    input = sys.stdin.read().split()
    idx = 0
    t = int(input[idx])
    idx += 1
    counts = defaultdict(int)
    for _ in range(t):
        op = input[idx]
        val = input[idx+1]
        idx += 2
        if op == '+':
            pattern = generate_pattern(val)
            counts[pattern] += 1
        elif op == '-':
            pattern = generate_pattern(val)
            counts[pattern] -= 1
        else:
            query_pattern = generate_query_pattern(val)
            print(counts.get(query_pattern, 0))

if __name__ == "__main__":
    main()

