import sys
from functools import lru_cache

def main():
    n, c0, c1 = map(int, sys.stdin.readline().split())
    if n == 1:
        print(min(c0, c1))
        return

    l = 0
    while (1 << l) < n:
        l += 1
    if l == 0:
        l = 1

    @lru_cache(maxsize=None)
    def f(n, l):
        if n == 0:
            return 0
        if l == 1:
            return 1 if n >= 1 else 0
        half = 1 << (l - 1)
        if n <= half:
            return n + f(n, l - 1)
        else:
            return half + f(half, l - 1) + f(n - half, l - 1)

    total_leaves = 1 << l
    if c0 <= c1:
        total_0s = f(n, l)
    else:
        total_0s_full = (total_leaves * l) // 2
        first_part = total_leaves - n
        min_0s = total_0s_full - f(first_part, l)
        total_0s = min_0s

    total_bits = n * l
    total_1s = total_bits - total_0s
    cost = total_0s * c0 + total_1s * c1
    print(cost)

if __name__ == "__main__":
