def main():
    import sys
    sys.setrecursionlimit(1000000)
    n, c0, c1 = map(int, sys.stdin.readline().split())

    def compute(n, prefer_zero):
        if n == 1:
            return (0, 0)
        m = n // 2
        r = n % 2
        if r == 0:
            a = m
            b = m
        else:
            a = m + 1
            b = m
        count_a, bits_a = compute(a, prefer_zero)
        count_b, bits_b = compute(b, prefer_zero)
        current_count = a
        total_count = current_count + count_a + count_b
        total_bits = a + b + bits_a + bits_b
        return (total_count, total_bits)

    if c0 <= c1:
        zeros, total = compute(n, True)
        cost = zeros * c0 + (total - zeros) * c1
    else:
        ones, total = compute(n, False)
        cost = ones * c1 + (total - ones) * c0
    print(cost)

if __name__ == "__main__":
    main()

