def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    tree = [[] for _ in range(n+1)]
    for i in range(2, n+1):
        pi, wi = map(int, sys.stdin.readline().split())
        tree[pi].append( (i, wi) )
    in_time = [0] * (n+1)
    out_time = [0] * (n+1)
    d = [0] * (n+1)
    timestamp = 0
    def dfs(node, parent_d):
        nonlocal timestamp
        timestamp += 1
        in_time[node] = timestamp
        d[node] = parent_d
        for child, weight in tree[node]:
            dfs(child, parent_d + weight)
        out_time[node] = timestamp
    dfs(1, 0)

    values = [0] * (n+1)
    for i in range(1, n+1):
        values[in_time[i]] = d[i] - a[i-1]

    st_data = []
    for i in range(1, n+1):
        st_data.append(values[i])

    class SegmentTree:
        def __init__(self, data):
            self.n = len(data)
            self.size = 1
            while self.size < self.n:
                self.size <<= 1
            self.tree = [[] for _ in range(2 * self.size)]
            # fill leaves
            for i in range(self.n):
                self.tree[self.size + i] = [data[i]]
            # fill the rest
            for i in range(self.size - 1, 0, -1):
                self.tree[i] = self.merge(self.tree[2*i], self.tree[2*i+1])

        def merge(self, left, right):
            res = []
            i = j = 0
            while i < len(left) and j < len(right):
                if left[i] < right[j]:
                    res.append(left[i])
                    i += 1
                else:
                    res.append(right[j])
                    j += 1
            res.extend(left[i:])
            res.extend(right[j:])
            return res

        def query(self, l, r, x):
            # query [l, r], 0-based, find elements <= x
            def _query(node, node_l, node_r, l, r):
                if node_r < l or node_l > r:
                    return 0
                if l <= node_l and node_r <= r:
                    return bisect.bisect_right(self.tree[node], x)
                mid = (node_l + node_r) // 2
                return _query(2*node, node_l, mid, l, r) + _query(2*node+1, mid+1, node_r, l, r)
            return _query(1, 0, self.size -1, l, r)

    if n == 0:
        print()
        return
    st = SegmentTree(st_data)

    res = [0] * (n+1)
    for v in range(1, n+1):
        l = in_time[v]
        r = out_time[v]
        x = d[v]
        # Convert to 0-based indices
        count = st.query(l-1, r-1, x)
        res[v] = count - 1

    for i in range(1, n+1):
        print(res[i])

main()

