def main():
    import sys
    a = sys.stdin.readline().strip()
    b = sys.stdin.readline().strip()

    n, m = len(a), len(b)
    i = j = 0

    # Find the longest prefix of b that is a subsequence of a
    while i < n and j < m:
        if a[i] == b[j]:
            j += 1
        i += 1

    # Now find the longest suffix of b that is a subsequence of a
    i = n - 1
    j = m - 1
    while i >= 0 and j >= 0:
        if a[i] == b[j]:
            j -= 1
        i -= 1

    # The result is the concatenation of the prefix and the suffix
    result = b[:m - j - 1] + b[j + 1:]
    if not result:
        print("-")
    else:
        print(result)

