def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n, m = int(data[0]), int(data[1])
    grid = data[2:]

    pigs = []
    wolves = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'P':
                pigs.append((i, j))
            elif grid[i][j] == 'W':
                wolves.append((i, j))

    adj_pigs = [[] for _ in range(len(wolves))]
    used_pigs = [False] * len(pigs)

    for w_idx, (wx, wy) in enumerate(wolves):
        for p_idx, (px, py) in enumerate(pigs):
            if abs(px - wx) + abs(py - wy) == 1:
                adj_pigs[w_idx].append(p_idx)

    result = 0

    for w_idx in range(len(wolves)):
        for p_idx in adj_pigs[w_idx]:
            if not used_pigs[p_idx]:
