from collections import Counter

def can_arrange_in_circle(nums):
    count = Counter(nums)
    max_freq = max(count.values())

    if max_freq > (len(nums) + 1) // 2:
        return "NO"

    # Check if the numbers can form a valid circle
    sorted_nums = sorted(count.keys())
    if len(sorted_nums) == 1:
        return "YES" if len(nums) == 1 else "NO"

    # Check for consecutive numbers
    for i in range(1, len(sorted_nums)):
        if sorted_nums[i] - sorted_nums[i-1] != 1:
            return "NO"

    # Check if the counts are valid for forming a circle
    if count[sorted_nums[0]] == count[sorted_nums[-1]]:
        if count[sorted_nums[0]] > 1:
            return "NO"
    elif count[sorted_nums[0]] > 1 or count[sorted_nums[-1]] > 1:
        return "NO"

    return "YES"

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    nums = list(map(int, data[1:]))
    print(can_arrange_in_circle(nums))

