import itertools

def main():
    s = sys.stdin.readline().strip()
    n = len(s)
    if n < 2:
        print()
        return

    # Precompute all possible positions for the two remaining cards
    # The game ends when exactly two cards are left, so we need to consider all pairs (i, j) with i < j
    # For each such pair, determine what the final binary number would be assuming optimal play

    # We will use memoization to store the best result for a given subsequence
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(l, r, turn):
        if r - l == 1:
            return (s[l], s[r]) if s[l] != '?' and s[r] != '?' else ('0', '0')
        if turn == 0:  # Masha's turn, wants to minimize
            min_result = ('1', '1')
            for i in range(l, r + 1):
                new_l = l
                new_r = r
                if i == l:
                    new_l = l + 1
                elif i == r:
                    new_r = r - 1
                else:
                    new_l = l
                    new_r = r
                res = dfs(new_l, new_r, 1)
                if res < min_result:
                    min_result = res
            return min_result
        else:  # Petya's turn, wants to maximize
            max_result = ('0', '0')
            for i in range(l, r + 1):
                new_l = l
                new_r = r
                if i == l:
                    new_l = l + 1
                elif i == r:
                    new_r = r - 1
                else:
                    new_l = l
                    new_r = r
