import re

text = input()
# Split the text into words and punctuation, preserving order
tokens = re.findall(r'\w+|[^\w\s]', text)

result = []
for i, token in enumerate(tokens):
    if re.match(r'[a-z]+', token):
        # It's a word
        if i > 0 and re.match(r'[a-z]+', tokens[i-1]):
            result.append(' ')
        result.append(token)
    else:
        # It's a punctuation mark
        if result and re.match(r'[a-z]+', result[-1]):
            result.append(token)
        else:
            result.append(' ' + token)

print(''.join(result))

