def determine_winner(a, b):
    if a == b:
        return (0, 0)
    if (a == 'R' and b == 'S') or (a == 'S' and b == 'P') or (a == 'P' and b == 'R'):
        return (0, 1)
    else:
        return (1, 0)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    A = data[1]
    B = data[2]

    lenA = len(A)
    lenB = len(B)

    total_nicks = 0
    total_pols = 0

    for i in range(n):
        a = A[i % lenA]
        b = B[i % lenB]
        nick, pol = determine_winner(a, b)
        total_nicks += nick
        total_pols += pol

    print(total_nicks, total_pols)

if __name__ == "__main__":
    main()

