import sys
import math

def max_game_result(n):
    memo = {}

    def dfs(x):
        if x == 1:
            return 1
        if x in memo:
            return memo[x]
        max_sum = 0
        for i in range(2, int(math.isqrt(x)) + 1):
            if x % i == 0:
                next_val = x // i
                current_sum = x + dfs(next_val)
                max_sum = max(max_sum, current_sum)
        memo[x] = max_sum
        return max_sum

    return dfs(n)

n = int(sys.stdin.readline())
print(max_game_result(n))

