import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    moves = data[1:]

    # Directions: 'U' (0, 1), 'D' (0, -1), 'L' (-1, 0), 'R' (1, 0)
    dir_map = {'U': (0, 1), 'D': (0, -1), 'L': (-1, 0), 'R': (1, 0)}

    # Possible directions for each move
    possible_moves = []
    for move in moves:
        if move == 'UL':
            possible_moves.append(['U', 'L'])
        elif move == 'UR':
            possible_moves.append(['U', 'R'])
        elif move == 'DL':
            possible_moves.append(['D', 'L'])
        elif move == 'DR':
            possible_moves.append(['D', 'R'])
        elif move == 'ULDR':
            possible_moves.append(['U', 'L', 'D', 'R'])

    # BFS to find all possible starting positions
    visited = set()
    queue = deque()
    queue.append((0, 0))
    visited.add((0, 0))

    for i in range(n):
        next_queue = deque()
        curr_moves = possible_moves[i]
        while queue:
            x, y = queue.popleft()
            for move in curr_moves:
                dx, dy = dir_map[move]
                nx, ny = x + dx, y + dy
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    next_queue.append((nx, ny))
        queue = next_queue

    print(len(visited))

if __name__ == "__main__":
    main()

