from itertools import permutations

def count_inversions(perm):
    inversions = 0
    n = len(perm)
    for i in range(n):
        for j in range(i + 1, n):
            if perm[i] > perm[j]:
                inversions += 1
    return inversions

def is_subsequence(sub, main):
    it = iter(main)
    return all(c in it for c in sub)

def find_best_match(lesha_words, archive_problems):
    best_similarity = -1
    best_index = -1
    best_perm = None

    for idx, (k, problem) in enumerate(archive_problems, 1):
        for perm in permutations(lesha_words):
            if is_subsequence(perm, problem):
                inv = count_inversions(perm)
                similarity = (len(lesha_words) * (len(lesha_words) + 1)) // 2 - inv
                if similarity > best_similarity or (similarity == best_similarity and idx < best_index):
                    best_similarity = similarity
                    best_index = idx
                    best_perm = perm
                break  # Once a valid permutation is found, no need to check others for this problem

    return best_index, best_similarity

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    lesha_words = input[1].split()
    m = int(input[2])
    archive = []
    for i in range(m):
        parts = input[3 + i].split()
        k = int(parts[0])
        words = parts[1:]
        archive.append((k, words))

    best_idx, best_sim = find_best_match(lesha_words, archive)

    if best_idx == -1:
        print("Brand new problem!")
    else:
        print(best_idx)
        p = best_sim
        bar = ':' + '|' * p + ':'
        print(bar)

if __name__ == "__main__":
    main()

