import sys
import math

def is_t_prime(x):
    if x < 4:
        return False
    sqrt_x = int(math.isqrt(x))
    if sqrt_x * sqrt_x != x:
        return False
    # Check if sqrt(x) is prime
    if sqrt_x < 2:
        return False
    for i in range(2, int(math.isqrt(sqrt_x)) + 1):
        if sqrt_x % i == 0:
            return False
    return True

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    numbers = list(map(int, data[1:n+1]))
    for num in numbers:
        if is_t_prime(num):
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    main()

