import sys

def main():
    import bisect
    n, d = map(int, sys.stdin.readline().split())
    x = list(map(int, sys.stdin.readline().split()))

    count = 0
    for i in range(n):
        max_x = x[i] + d
        j = bisect.bisect_right(x, max_x) - 1
        k = j - i
        if k >= 2:
            count += (k * (k - 1)) // 2
        elif k == 1:
            count += 0
        else:
            pass
    print(count)

if __name__ == "__main__":
    main()

