def apply_permutation(p, q, inverse=False):
    if inverse:
        inv_q = [0] * (len(q) + 1)
        for i in range(1, len(q) + 1):
            inv_q[q[i - 1]] = i
        q = inv_q
    return [p[q[i] - 1] for i in range(len(p))]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    q = list(map(int, data[2:2 + n]))
    s = list(map(int, data[2 + n:2 + 2 * n]))

    initial = list(range(1, n + 1))
    current = initial[:]

    # Check if initial is s and k == 0
    if k == 0:
        if current == s:
            print("YES")
        else:
            print("NO")
        return

    # Check if initial is s and k > 0
    if current == s:
        print("NO")
        return

    # Try all possible sequences of operations (k steps, each can be forward or inverse)
    from itertools import product

    for ops in product([0, 1], repeat=k):
        current = initial[:]
        found = False
        for op in ops:
            if op == 0:
                current = apply_permutation(current, q)
            else:
                current = apply_permutation(current, q, inverse=True)
            if current == s:
                found = True
                break
        if not found:
            continue
        # Check if s was ever present before the k-th move
        valid = True
        current = initial[:]
        for i in range(k):
            if current == s:
                valid = False
                break
            if ops[i] == 0:
                current = apply_permutation(current, q)
            else:
                current = apply_permutation(current, q, inverse=True)
        if valid:
            print("YES")
            return
    print("NO")

main()

