def apply_permutation(p, q, inverse=False):
    if inverse:
        inv_q = [0] * (len(q) + 1)
        for i in range(1, len(q) + 1):
            inv_q[q[i - 1]] = i
        q = inv_q
    return [p[q[i] - 1] for i in range(len(p))]

