        res = 0
        if i < n:
            new_balance = balance + 1
            if new_balance >= 0:
                res += dp(i + 1, j, new_balance)
        if j < m:
            new_balance = balance - 1
            if new_balance >= -k:
                res += dp(i, j + 1, new_balance)
        return res

    valid_sequences = dp(0, 0, 0)
    total_sequences = math.comb(n + m, n)

    probability = valid_sequences / total_sequences
    print(f"{probability:.10f}")

