import sys

def main():
    chat = set()
    total_traffic = 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line.startswith('+'):
            name = line[1:]
            chat.add(name)
        elif line.startswith('-'):
            name = line[1:]
            if name in chat:
                chat.remove(name)
        else:
            sender, message = line.split(':', 1)
            message_length = len(message)
            total_traffic += message_length * len(chat)

    print(total_traffic)

if __name__ == "__main__":
    main()

