    data = input().split()
    n = int(data[0])
    heights = list(map(int, data[1:]))

    result = 0

    # For each hill, find the next greater to the left and right
    # Using a monotonic stack approach
    next_greater_left = [-1] * n
    next_greater_right = [-1] * n
    stack = []

    for i in range(n):
        while stack and heights[stack[-1]] < heights[i]:
            stack.pop()
        if stack:
            next_greater_left[i] = stack[-1]
        else:
            next_greater_left[i] = -1
        stack.append(i)

    stack = []
    for i in range(n-1, -1, -1):
        while stack and heights[stack[-1]] < heights[i]:
            stack.pop()
        if stack:
            next_greater_right[i] = stack[-1]
        else:
            next_greater_right[i] = -1
        stack.append(i)

    # Count pairs
    for i in range(n):
        # Pairs where current is the highest in between
        left = next_greater_left[i]
        right = next_greater_right[i]

        if left == -1:
            left_count = i
        else:
            left_count = i - left - 1

        if right == -1:
            right_count = n - i - 1
        else:
            right_count = right - i - 1

        result += left_count + right_count + 1

    print(result)

