n, m, a, b = map(int, input().split())

# Calculate the number of full rows and remaining folders
def count_selections(n, m, a, b):
    def get_row(x):
        return (x - 1) // m

    row_a = get_row(a)
    row_b = get_row(b)

    # If all folders are in the same row
    if row_a == row_b:
        return 1

    # Otherwise, we need to select the first partial row, all full rows in between, and the last partial row
    return 2 + (row_b - row_a - 1)

print(count_selections(n, m, a, b))

