n, m, a, b = map(int, input().split())

def count_selections(n, m, a, b):
    # Number of full rows in the range [a, b]
    first_row = (a - 1) // m
    last_row = (b - 1) // m
    if first_row == last_row:
        # All in one row
        return 1
    else:
        # First partial row and last partial row
        # Plus full rows in between
        return 2 + (last_row - first_row - 1)

print(count_selections(n, m, a, b))

