def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    start, end = data[0], data[1]
    n = int(data[2])

    positions = ['v', '<', '^', '>']

    def get_index(pos):
        return positions.index(pos)

    start_idx = get_index(start)
    end_idx = get_index(end)

    clockwise_steps = (end_idx - start_idx) % 4
    counter_steps = (start_idx - end_idx) % 4

    if n % 4 == 0:
        print("undefined")
    elif (n % 4) == clockwise_steps:
        print("cw")
    elif (n % 4) == counter_steps:
        print("ccw")
    else:
        print("undefined")

if __name__ == "__main__":
    main()

